'use strict';
const root=document.querySelector('#stage'),controls=document.querySelector('#controls'),diagram=document.querySelector('#diagram');
const rt=Math.SQRT1_2,states={zero:[1,0],one:[0,1],plus:[rt,rt],minus:[rt,-rt]},ket={zero:'|0\\rangle',one:'|1\\rangle',plus:'|+\\rangle',minus:'|-\\rangle'};
const expanded={zero:'|0\\rangle',one:'|1\\rangle',plus:'\\frac{|0\\rangle+|1\\rangle}{\\sqrt2}',minus:'\\frac{|0\\rangle-|1\\rangle}{\\sqrt2}'};
const outputs={H:{zero:['plus',1],one:['minus',1],plus:['zero',1],minus:['one',1]},X:{zero:['one',1],one:['zero',1],plus:['plus',1],minus:['minus',-1]}};
let mode='single',input='zero',operation='H',revealed=false,step=0,mathQueue=Promise.resolve();
const inline=t=>'\\('+t+'\\)';
const probability=v=>v===0?'0':Math.abs(v)===1?'1':'\\tfrac12';
const math=t=>'\\['+t+'\\]';
function typeset(){mathQueue=mathQueue.then(()=>window.MathJax?.startup?.promise).then(()=>window.MathJax?.typesetPromise?.([diagram]));return mathQueue;}
function draw(){const k=Math.min(innerWidth/1120,innerHeight/630);root.style.transform=`scale(${k})`;root.style.marginLeft=`${Math.max(0,(innerWidth-1120*k)/2)}px`;root.style.marginTop=`${Math.max(0,(innerHeight-630*k)/2)}px`;}
function sphere(key){const project=([x,y,z])=>[150+105*(Math.sqrt(3)/2*x-.5*y),142+105*(.25*x+Math.sqrt(3)/4*y-Math.sqrt(3)/2*z)];let axes='';[[1,0,0],[0,1,0],[0,0,1]].forEach((v,i)=>{const a=project(v.map(x=>-1.14*x)),b=project(v.map(x=>1.14*x));axes+=`<path d="M${a}L${b}" stroke="#bbcddd"/><text x="${b[0]+6}" y="${b[1]-5}" fill="#617f96" font-size="20">${'xyz'[i]}</text>`;});const eq=Array.from({length:81},(_,i)=>project([Math.cos(i*Math.PI/40),Math.sin(i*Math.PI/40),0]).join(',')).join(' ');let vector='';if(key){const [a,b]=states[key],p=project([2*a*b,0,a*a-b*b]);vector=`<path d="M150 142L${p}" stroke="#176ca2" stroke-width="4"/><circle cx="${p[0]}" cy="${p[1]}" r="7" fill="#176ca2"/>`;}return `<svg class="plot" viewBox="0 0 300 290" role="img" aria-label="${key?'布洛赫球上的状态':'输出待揭示'}"><circle cx="150" cy="142" r="105" fill="#f7fafc" stroke="#a7c2d8"/>${axes}<polyline points="${eq}" fill="none" stroke="#bbcddd"/>${vector}</svg>`;}
function card(label,key,sign=1){const known=!!key;let expression=known?(sign<0?'-':'')+ket[key]:'';if(key==='plus'||key==='minus')expression+='='+ (sign<0?'\\frac{-|0\\rangle+|1\\rangle}{\\sqrt2}':expanded[key]);return `<section data-state="${key||'pending'}" data-sign="${sign}" class="state ${known?'':'future'}"><h2>${label}</h2>${sphere(key)}<div class="formula">${known?math(expression):'<span class="pending">待揭示</span>'}</div><div class="prob">${known?`<span>${inline('P(0)='+probability(states[key][0]))}</span><span>${inline('P(1)='+probability(states[key][1]))}</span>`:''}</div></section>`;}
function arrow(g,visible=true){return `<div class="operator ${visible?'':'future'}">${math(g==='H'?'U_{\\mathrm H}':'X')}<svg class="flow-arrow" viewBox="0 0 90 20" aria-hidden="true"><path d="M3 10H85M77 3L85 10L77 17" fill="none" stroke="currentColor" stroke-width="2"/></svg></div>`;}
function render(){window.MathJax?.typesetClear?.([diagram]);diagram.className=mode==='twice'?'sequence':'';if(mode==='single'){const [out,sign]=outputs[operation][input];diagram.innerHTML=card('输入',input)+arrow(operation)+card('输出',revealed?out:null,sign);document.querySelector('#show').disabled=revealed;document.querySelector('#show').textContent=revealed?'已显示输出':'显示输出';}else{diagram.innerHTML=card('初态','zero')+arrow('H',step>=1)+card('第一次 H 后',step>=1?'plus':null)+arrow('H',step>=2)+card('第二次 H 后',step>=2?'zero':null);const next=document.querySelector('#next');next.disabled=step===2;next.textContent=['施加第一次 H','施加第二次 H','已完成'][step];}typeset();}
function setMode(value){mode=value;document.querySelector('#single').setAttribute('aria-selected',value==='single');document.querySelector('#twice').setAttribute('aria-selected',value==='twice');if(value==='single'){revealed=false;controls.innerHTML='<label>输入 <select id="input"><option value="zero">0 态</option><option value="one">1 态</option><option value="plus">+ 态</option><option value="minus">− 态</option></select></label><label>门 <select id="gate"><option value="H">Hadamard</option><option value="X">X 翻转</option></select></label><button id="show" class="primary">显示输出</button>';document.querySelector('#input').value=input;document.querySelector('#gate').value=operation;document.querySelector('#input').onchange=e=>{input=e.target.value;revealed=false;render();};document.querySelector('#gate').onchange=e=>{operation=e.target.value;revealed=false;render();};document.querySelector('#show').onclick=()=>{revealed=true;render();};}else{step=0;controls.innerHTML='<span>从0态开始</span><button id="reset">重新开始</button><button id="next" class="primary">施加第一次 H</button>';document.querySelector('#reset').onclick=()=>{step=0;render();};document.querySelector('#next').onclick=()=>{step=Math.min(2,step+1);render();};}render();}
document.querySelector('#single').onclick=()=>setMode('single');document.querySelector('#twice').onclick=()=>setMode('twice');document.querySelector('#full').onclick=async()=>{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();};document.addEventListener('fullscreenchange',()=>{document.querySelector('#full').textContent=document.fullscreenElement?'退出全屏 ↙':'全屏 ↗';draw();});addEventListener('resize',draw);setMode('single');draw();window.gateDemoReady=true;
addEventListener('keydown',e=>{if(e.key==='Escape'&&document.fullscreenElement){e.preventDefault();document.exitFullscreen();}},true);
